#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int findMaxBucket(const std::vector<int>& buckets) {
    for (int i = buckets.size() - 1; i >= 0; i--) {
        if (buckets[i] > 0) {
            return i;
        }
    }
    return -1;
}

int main() {
    int length, limitB;
    std::cin >> length >> limitB;
    std::vector<int> sequenceArr(length);
    for (int idx = 0; idx < length; ++idx) {
        std::cin >> sequenceArr[idx];
    }

    std::vector<int> bucketArray(101, 0);
    int totalSumB = 0;

    int evenCounter = 0;
    int oddCounter = 0;
    int segmentStartIdx = 0;
    int totalSegmentsCount = 0;
    int currentIndex = 1;

    for (int i = 0; i < static_cast<int>(sequenceArr.size()) - 1; ++i) {
        if (sequenceArr[i] % 2 == 0) {
            ++evenCounter;
        } else {
            ++oddCounter;
        }

        if (evenCounter == oddCounter) {
            int diffValue = std::abs(sequenceArr[i + 1] - sequenceArr[i]);
            int maxBucketVal = findMaxBucket(bucketArray);
            if (totalSumB > limitB && diffValue < maxBucketVal) {
                totalSumB -= maxBucketVal;
                bucketArray[maxBucketVal]--;
                bucketArray[diffValue]++;
                totalSumB += diffValue;
            } else if (totalSumB < limitB) {
                totalSumB += diffValue;
                bucketArray[diffValue]++;
                ++totalSegmentsCount;
                segmentStartIdx = i + 1;
            }
            if (i == static_cast<int>(sequenceArr.size()) - 2 && currentIndex < static_cast<int>(sequenceArr.size()) - 1) {
                i = segmentStartIdx++;
                evenCounter = 0;
                oddCounter = 0;
            }
        }
    }

    int i = static_cast<int>(bucketArray.size()) - 1;
    while (totalSumB > limitB && i >= 0) {
        if (bucketArray[i] > 0) {
            totalSumB -= i;
            --bucketArray[i];
            if (totalSumB <= limitB) break;
        } else {
            --i;
        }
    }

    std::cout << totalSegmentsCount << std::endl;
    return 0;
}
